"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
import heapq
from collections import deque

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    O((V+E) log V) using Dijkstra's algorithm with a min-heap.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist = {n: float('inf') for n in nodes}
    prev = {n: None for n in nodes}
    dist[source] = 0

    # Min-heap: (distance, node)
    heap = [(0, source)]
    visited = set()

    while heap:
        current_dist, u = heapq.heappop(heap)

        if u in visited:
            continue
        visited.add(u)

        # Early termination if we've reached the target
        if u == target:
            break

        # Relax edges using adjacency list
        for v, weight in graph.neighbors(u):
            new_dist = current_dist + weight
            if new_dist < dist[v]:
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(heap, (new_dist, v))

    if dist[target] == float('inf'):
        return None, []

    # Reconstruct path
    path = []
    current = target
    while current is not None:
        path.append(current)
        current = prev[current]
    path.reverse()
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    O((V+E) log V) - Single Dijkstra pass.
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist = {n: float('inf') for n in nodes}
    prev = {n: None for n in nodes}
    dist[source] = 0

    # Min-heap: (distance, node)
    heap = [(0, source)]
    visited = set()

    while heap:
        current_dist, u = heapq.heappop(heap)

        if u in visited:
            continue
        visited.add(u)

        # Relax edges using adjacency list
        for v, weight in graph.neighbors(u):
            new_dist = current_dist + weight
            if new_dist < dist[v]:
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(heap, (new_dist, v))

    # Build result with paths
    result = {}
    for node in nodes:
        if dist[node] != float('inf'):
            # Reconstruct path
            path = []
            current = node
            while current is not None:
                path.append(current)
                current = prev[current]
            path.reverse()
            result[node] = (dist[node], path)

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    O((V+E) log V) - Early-termination Dijkstra.
    """
    nodes = graph.nodes
    if source not in nodes:
        return []

    dist = {n: float('inf') for n in nodes}
    dist[source] = 0

    # Min-heap: (distance, node)
    heap = [(0, source)]
    visited = set()
    result = []

    while heap and len(result) < k:
        current_dist, u = heapq.heappop(heap)

        if u in visited:
            continue
        visited.add(u)

        # Add to result (excluding source)
        if u != source:
            result.append((u, current_dist))

        # Relax edges using adjacency list
        for v, weight in graph.neighbors(u):
            new_dist = current_dist + weight
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(heap, (new_dist, v))

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    O(V + E) - Simple BFS.
    """
    if source not in graph.nodes or target not in graph.nodes:
        return False

    if source == target:
        return True

    visited = set()
    queue = deque([source])
    visited.add(source)

    while queue:
        u = queue.popleft()

        for v, _ in graph.neighbors(u):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                queue.append(v)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    O(V + E) - BFS with undirected adjacency.
    """
    # Build undirected adjacency list
    undirected_adj = {node: set() for node in graph.nodes}
    for node in graph.nodes:
        for neighbor, _ in graph.neighbors(node):
            undirected_adj[node].add(neighbor)
            undirected_adj[neighbor].add(node)

    visited = set()
    components = []

    for node in graph.nodes:
        if node in visited:
            continue

        # BFS to find all nodes in this component
        component = set()
        queue = deque([node])
        visited.add(node)
        component.add(node)

        while queue:
            u = queue.popleft()
            for v in undirected_adj[u]:
                if v not in visited:
                    visited.add(v)
                    component.add(v)
                    queue.append(v)

        components.append(component)

    return components
```

**Key optimizations:**

1. **`shortest_path`**: Uses Dijkstra's algorithm with a min-heap instead of repeatedly scanning all nodes and edges. Complexity: O((V+E) log V).

2. **`all_shortest_paths`**: Single Dijkstra pass from source, then reconstructs all paths. Complexity: O((V+E) log V) instead of V × O(V·E²).

3. **`k_nearest`**: Early-termination Dijkstra that stops after finding k nodes. Complexity: O((V+E) log V) worst case, often better with early termination.

4. **`is_reachable`**: Simple BFS traversal instead of running full shortest path. Complexity: O(V+E).

5. **`connected_components`**: Builds undirected adjacency in O(V+E), then uses BFS for each component. Complexity: O(V+E) total.

All functions maintain exact API compatibility with identical signatures and return types.
